const MAX_RETRY_AFTER_MS = 300_000;

/**
 * Parse the gateway's explicitly millisecond-valued JSON fields. Keeping this
 * separate from the seconds parser is important: a numeric `retryAfter: 7`
 * means seven seconds, while `retryAfterMs: 7` means seven milliseconds.
 */
export function boundedRetryAfterMs(value: unknown): number | undefined {
    const number = typeof value === 'number'
        ? value
        : typeof value === 'string' && /^\d+(?:\.\d+)?$/.test(value.trim())
            ? Number(value.trim())
            : NaN;
    if (!Number.isFinite(number) || number < 0) return undefined;
    return Math.min(MAX_RETRY_AFTER_MS, Math.floor(number));
}

/** Parse a JSON retry-after value whose unit is seconds. */
export function boundedRetryAfterSecondsMs(value: unknown): number | undefined {
    const number = typeof value === 'number'
        ? value
        : typeof value === 'string' && /^\d+(?:\.\d+)?$/.test(value.trim())
            ? Number(value.trim())
            : NaN;
    if (!Number.isFinite(number) || number < 0) return undefined;
    return Math.min(MAX_RETRY_AFTER_MS, Math.ceil(number * 1_000));
}

/** Parse an HTTP Retry-After header (delta-seconds or HTTP date). */
export function retryAfterHeaderMs(value: unknown, now = Date.now()): number | undefined {
    if (typeof value !== 'string') return boundedRetryAfterSecondsMs(value);
    const normalized = value.trim();
    if (!normalized) return undefined;
    const seconds = boundedRetryAfterSecondsMs(normalized);
    if (seconds !== undefined) return seconds;
    const date = Date.parse(normalized);
    if (!Number.isFinite(date)) return undefined;
    return Math.min(MAX_RETRY_AFTER_MS, Math.max(0, date - now));
}

export function responseRetryAfterMs(response: Response, payload: unknown, now = Date.now()): number | undefined {
    const body = payload && typeof payload === 'object' && !Array.isArray(payload)
        ? payload as Record<string, unknown>
        : undefined;
    const error = body?.error && typeof body.error === 'object' && !Array.isArray(body.error)
        ? body.error as Record<string, unknown>
        : undefined;
    const details = body?.details && typeof body.details === 'object' && !Array.isArray(body.details)
        ? body.details as Record<string, unknown>
        : undefined;
    const sources = [error, details, body];
    for (const source of sources) {
        const milliseconds = boundedRetryAfterMs(source?.retryAfterMs)
            ?? boundedRetryAfterMs(source?.retry_after_ms);
        if (milliseconds !== undefined) return milliseconds;
    }
    for (const source of sources) {
        const seconds = boundedRetryAfterSecondsMs(source?.retryAfter)
            ?? boundedRetryAfterSecondsMs(source?.retry_after);
        if (seconds !== undefined) return seconds;
    }
    return retryAfterHeaderMs(response.headers.get('retry-after'), now);
}

interface ManagedGatewayStreamCallbacks {
    readonly contentOwnerId?: string;
    readonly onRequestId?: (requestId: string, owner?: { readonly userId: string; readonly platformOrigin: string }) => Promise<void>;
    readonly onPricingUpdate?: (update: ManagedPriceUpdate) => void | Promise<void>;
    readonly onProviderEvent?: (event: AgentModelProviderEvent) => void | Promise<void>;
    readonly onTextDelta?: (delta: string) => void | Promise<void>;
}

function streamUsage(value: unknown, usageKnown?: unknown): {
    readonly inputTokens: number;
    readonly outputTokens: number;
    readonly usageKnown: boolean;
    readonly web_search?: number;
    readonly web_fetch?: number;
} {
    const item = value && typeof value === 'object' && !Array.isArray(value)
        ? value as Record<string, unknown>
        : {};
    return {
        inputTokens: nonNegativeInteger(item.inputTokens ?? item.input_tokens ?? item.prompt_tokens),
        outputTokens: nonNegativeInteger(item.outputTokens ?? item.output_tokens ?? item.completion_tokens),
        usageKnown: usageKnown === true || item.usageKnown === true,
        ...(typeof item.web_search === 'number' && Number.isSafeInteger(item.web_search) && item.web_search >= 0
            ? { web_search: item.web_search } : {}),
        ...(typeof item.web_fetch === 'number' && Number.isSafeInteger(item.web_fetch) && item.web_fetch >= 0
            ? { web_fetch: item.web_fetch } : {})
    };
}

function streamErrorFromPayload(response: Response, payload: unknown): PlatformRequestError {
    const body = payload && typeof payload === 'object' && !Array.isArray(payload)
        ? payload as Record<string, unknown>
        : {};
    const error = body.error && typeof body.error === 'object' && !Array.isArray(body.error)
        ? body.error as Record<string, unknown>
        : body;
    return new PlatformRequestError(
        String(error.code || 'PLATFORM_REQUEST_FAILED'),
        String(error.message || '平台请求失败'),
        response.status,
        responseRetryAfterMs(response, payload),
        { ...(body.details && typeof body.details === 'object' ? body.details : {}), ...error },
        true
    );
}

function nonNegativeInteger(value: unknown): number {
    const number = Number(value);
    return Number.isSafeInteger(number) && number >= 0 ? number : 0;
}

function validCatalogKeyPrice(keyPrice: PlatformOffering['keyPrice'], keyPriceQuoteId: string | undefined): boolean {
    if (!keyPrice) return true;
    if (!keyPriceQuoteId || keyPrice.quoteRequired !== true) return false;
    const { minimumMultiplierBps: minimum, maximumMultiplierBps: maximum, selectedMultiplierBps: selected } = keyPrice;
    if (keyPrice.pricingMode === 'direct') return minimum === null && maximum === null && selected === null;
    return keyPrice.pricingMode === 'official_key_multiplier'
        && typeof minimum === 'number' && typeof maximum === 'number' && typeof selected === 'number'
        && [minimum, maximum, selected].every(value => Number.isSafeInteger(value) && value >= 0)
        && minimum <= selected && selected <= maximum;
}

/** Only well-formed option keys and states cross into the picker. */
function normalizeReasoningEvidence(value: unknown): PlatformOffering['reasoningEvidence'] {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
    const entries = Object.entries(value as Record<string, unknown>).slice(0, 32)
        .filter(([key, state]) => isReasoningOptionKey(key) && (state === 'verified' || state === 'accepted' || state === 'rejected'));
    return entries.length ? Object.fromEntries(entries) as PlatformOffering['reasoningEvidence'] : undefined;
}

/** A global-catalog cursor from the platform: opaque, bounded, URL-safe. */
function catalogCursor(value: unknown): string | undefined {
    return typeof value === 'string' && /^[A-Za-z0-9._~:+=-]{1,4096}$/.test(value) ? value : undefined;
}

/**
 * Removes the exact credential values used for a call from an upstream body or an error (message, stack, the RPC
 * data and nested diagnostics), whatever the key looks like: an API that echoes the key back must not carry it into
 * RPC, logs, stored failures or the screen (audit A22-05).
 */
function scrubCredentialValues<T>(value: T, secrets: readonly string[]): T {
    const raw = [...new Set(secrets.filter(secret => typeof secret === 'string' && secret.trim().length >= 8).map(secret => secret.trim()))];
    if (!raw.length || value === null || value === undefined) return value;
    // Every form a key travels or is echoed in: as sent in a query string or form (percent or plus encoded), inside a
    // JSON string (escaped quotes and backslashes), and base64 as in Basic authorization (audit B20-01).
    const forms = new Set<string>();
    for (const secret of raw) {
        forms.add(secret);
        forms.add(encodeURIComponent(secret));
        forms.add(new URLSearchParams({ k: secret }).toString().slice(2));
        forms.add(JSON.stringify(secret).slice(1, -1));
        forms.add(Buffer.from(secret).toString('base64').replace(/=+$/, ''));
    }
    const keys = [...forms].filter(form => form.length >= 8).sort((left, right) => right.length - left.length);
    const scrub = (text: string): string => keys.reduce((out, secret) => out.includes(secret) ? out.split(secret).join('[REDACTED]') : out, text);
    const seen = new WeakMap<object, unknown>();
    const walk = (current: unknown, depth: number): unknown => {
        if (typeof current === 'string') return scrub(current);
        if (!current || typeof current !== 'object' || depth > 24) return current;
        if (seen.has(current)) return seen.get(current);
        if (current instanceof Error) {
            const error = current as Error & Record<string, unknown>;
            seen.set(current, current);
            if (typeof error.message === 'string') error.message = scrub(error.message);
            if (typeof error.stack === 'string') error.stack = scrub(error.stack);
            for (const field of ['data', 'readableError', 'detail', 'details', 'domainError', 'cause', 'body', 'response']) {
                if (!(field in error) || error[field] === undefined) continue;
                try { Object.defineProperty(error, field, { value: walk(error[field], depth + 1), writable: true, configurable: true, enumerable: Object.prototype.propertyIsEnumerable.call(error, field) }); }
                catch { /* a sealed field stays; message and stack are clean */ }
            }
            return current;
        }
        if (Array.isArray(current)) {
            const copy: unknown[] = [];
            seen.set(current, copy);
            for (const item of current) copy.push(walk(item, depth + 1));
            return copy;
        }
        const prototype = Object.getPrototypeOf(current);
        if (prototype !== Object.prototype && prototype !== null) return current;
        const copy: Record<string, unknown> = {};
        seen.set(current, copy);
        for (const [key, item] of Object.entries(current)) copy[scrub(key)] = walk(item, depth + 1);
        return copy;
    };
    return walk(value, 0) as T;
}

/** Whether a failed media submission may still have reached the provider (so retrying could pay twice). */
function mediaSubmissionMayHaveArrived(error: unknown): boolean {
    const seen = new Set<unknown>();
    for (let current: any = error; current && !seen.has(current); current = current.cause) {
        seen.add(current);
        if (['ENOTFOUND', 'EAI_AGAIN', 'ECONNREFUSED', 'EHOSTUNREACH', 'ENETUNREACH', 'CERT_HAS_EXPIRED', 'DEPTH_ZERO_SELF_SIGNED_CERT',
            'UNABLE_TO_VERIFY_LEAF_SIGNATURE', 'ERR_TLS_CERT_ALTNAME_INVALID', 'UND_ERR_CONNECT_TIMEOUT'].includes(String(current.code))) return false;
    }
    return true;
}

interface ConversationImportMapEntry { sessionId: string; importedAt: number; sourceUpdatedAt: number }

/** A conversation imported from another app that was continued in NextMux: it has turns the import did not write. */
function continuedAfterImport(record: Record<string, unknown>, sessionId: string): boolean {
    const turns = Array.isArray(record.turns) ? record.turns as { id?: unknown }[] : [];
    const prefix = `${sessionId}-t`;
    return turns.some(turn => {
        const id = String(turn?.id ?? '');
        return !id.startsWith(prefix) || !/^\d+$/.test(id.slice(prefix.length));
    });
}

/**
 * Every offering of a page that passes validation. One offering the platform describes in a newer or broken shape is
 * left out; it must not empty the whole model list (a new price source once did exactly that).
 */
function normalizeCatalogOfferings(offerings: readonly PlatformOffering[]): PlatformOffering[] {
    const valid: PlatformOffering[] = [];
    for (const offering of offerings) {
        try { valid.push(normalizeCatalogOffering(offering)); }
        catch { /* skipped: quote evidence the desktop cannot read is never shown or used */ }
    }
    if (offerings.length && !valid.length) throw new PlatformRequestError('CATALOG_INVALID', '模型目录返回了不兼容的数据');
    return valid;
}

function normalizeCatalogOffering(offering: PlatformOffering): PlatformOffering {
    // The fields every picker reads: an offering without them is left out, never shown half-formed (audit A04-03).
    if (!offering || typeof offering.id !== 'string' || offering.status === 'active' && (typeof offering.canonicalModel !== 'string'
        || !offering.canonicalModel.trim() || !Array.isArray(offering.workbenches))) throw new PlatformRequestError('CATALOG_INVALID', '模型目录返回了不兼容的数据');
    const { storeTagline, storeDescription, ...catalogOffering } = offering;
    const keyPriceQuoteId = requireValidKeyPriceQuoteId(offering.keyPriceQuoteId);
    const keyPrice = offering.keyPrice;
    if (!validCatalogKeyPrice(keyPrice, keyPriceQuoteId)) {
        throw new PlatformRequestError('CATALOG_INVALID', '模型目录的价格授权无效');
    }
    const merchantId = typeof offering.merchantId === 'string' ? offering.merchantId.trim() : '';
    const recommendedRank = nonNegativeInteger(offering.recommendedRank);
    const routeCapacity = normalizeModelCapacity({
        contextTokens: offering.routeContextTokens,
        inputTokens: offering.routeInputTokens,
        maximumOutputTokens: offering.routeMaximumOutputTokens
    });
    return {
        ...catalogOffering,
        nativeWebResearch: normalizeManagedWebResearch(offering.nativeWebResearch),
        ...normalizePublicMerchantStoreProfile({ storeTagline, storeDescription }),
        routeContextTokens: routeCapacity.contextTokens,
        routeInputTokens: routeCapacity.inputTokens,
        routeMaximumOutputTokens: routeCapacity.maximumOutputTokens,
        contextTokens: undefined, inputTokens: undefined, maximumOutputTokens: undefined,
        ...normalizeModelCapacity(offering),
        ...(offering.pricingDetails ? { pricingDetails: normalizePublicPriceDetails(offering.pricingDetails) } : {}),
        keyPriceQuoteId,
        merchantId,
        recommendedRank,
        recommended: offering.recommended === true || recommendedRank > 0,
        merchantTrustScore: Math.min(100, nonNegativeInteger(offering.merchantTrustScore)),
        likes: nonNegativeInteger(offering.likes),
        dislikes: nonNegativeInteger(offering.dislikes),
        reasoningEvidence: normalizeReasoningEvidence(offering.reasoningEvidence)
    };
}

function normalizeRelayFeedback(value: PlatformRelayFeedback): PlatformRelayFeedback {
    let requestId: string;
    try {
        requestId = relayFeedbackRequestId(value?.requestId);
    } catch {
        throw new PlatformRequestError('FEEDBACK_INVALID', '平台返回了无效的评分数据');
    }
    const vote: RelayFeedbackVote = value?.vote === 'up' || value?.vote === 'down' ? value.vote : null;
    return {
        requestId,
        merchantId: String(value?.merchantId || ''),
        vote,
        likes: nonNegativeInteger(value?.likes),
        dislikes: nonNegativeInteger(value?.dislikes),
        createdAt: value?.createdAt == null ? null : nonNegativeInteger(value.createdAt),
        updatedAt: value?.updatedAt == null ? null : nonNegativeInteger(value.updatedAt)
    };
}

function normalizeRelayFeedbackBatch(value: PlatformRelayFeedbackBatch): PlatformRelayFeedbackBatch {
    if (!value || typeof value !== 'object' || !Array.isArray(value.requestIds)
        || !Array.isArray(value.targets) || !value.aggregates || typeof value.aggregates !== 'object'
        || !Array.isArray(value.aggregates.merchants)) {
        throw new PlatformRequestError('FEEDBACK_INVALID', '平台返回了无效的评分数据');
    }
    let requestIds: readonly string[];
    try {
        requestIds = relayFeedbackRequestIds(value.requestIds);
    } catch {
        throw new PlatformRequestError('FEEDBACK_INVALID', '平台返回了无效的评分数据');
    }
    if (requestIds.length !== value.requestIds.length) {
        throw new PlatformRequestError('FEEDBACK_INVALID', '平台返回了无效的评分数据');
    }
    const vote: RelayFeedbackVote = value?.vote === 'up' || value?.vote === 'down' ? value.vote : null;
    const targets = value.targets.map(target => ({
        merchantId: String(target?.merchantId || ''),
        providerName: String(target?.providerName || ''),
        endpointId: String(target?.endpointId || ''),
        endpointName: String(target?.endpointName || ''),
        modelId: String(target?.modelId || ''),
        modelName: String(target?.modelName || ''),
        canonicalModel: String(target?.canonicalModel || ''),
        vote: target?.vote === 'up' || target?.vote === 'down' ? target.vote : null,
        likes: nonNegativeInteger(target?.likes),
        dislikes: nonNegativeInteger(target?.dislikes),
        requestCount: nonNegativeInteger(target?.requestCount),
        attemptCount: nonNegativeInteger(target?.attemptCount)
    }));
    const merchants = value.aggregates.merchants.map(merchant => ({
        merchantId: String(merchant?.merchantId || ''),
        providerName: String(merchant?.providerName || ''),
        likes: nonNegativeInteger(merchant?.likes),
        dislikes: nonNegativeInteger(merchant?.dislikes)
    }));
    return {
        groupId: typeof value?.groupId === 'string' && value.groupId ? value.groupId : null,
        requestIds,
        vote,
        createdAt: value?.createdAt == null ? null : nonNegativeInteger(value.createdAt),
        updatedAt: value?.updatedAt == null ? null : nonNegativeInteger(value.updatedAt),
        targets,
        aggregates: {
            requestCount: nonNegativeInteger(value?.aggregates?.requestCount),
            attemptCount: nonNegativeInteger(value?.aggregates?.attemptCount),
            targetCount: nonNegativeInteger(value?.aggregates?.targetCount),
            merchantCount: nonNegativeInteger(value?.aggregates?.merchantCount),
            merchants
        }
    };
}

function relayFeedbackRequestId(requestId: string): string {
    const normalized = String(requestId || '');
    if (!isRelayFeedbackRequestId(normalized)) {
        throw new PlatformRequestError('FEEDBACK_REQUEST_INVALID', '反馈请求编号无效');
    }
    return normalized;
}

function relayFeedbackRequestIds(requestIds: readonly string[]): readonly string[] {
    if (!Array.isArray(requestIds) || requestIds.length < 1 || requestIds.length > RELAY_FEEDBACK_MAX_REQUEST_IDS
        || requestIds.reduce((sum, requestId) => sum + (typeof requestId === 'string' ? requestId.length : 0), 0) > RELAY_FEEDBACK_MAX_REQUEST_ID_CHARACTERS
        || requestIds.some(requestId => !isRelayFeedbackRequestId(requestId))) {
        throw new PlatformRequestError('FEEDBACK_REQUEST_INVALID', '反馈请求编号无效');
    }
    return normalizeRelayFeedbackRequestIds(requestIds);
}

class ResumableAgentRunError extends PlatformRequestError {
    constructor(
        code: string,
        message: string,
        readonly resumeCheckpointId: string,
        readonly failure?: AgentModelFailure,
        readonly billing?: DesktopAgentRunFailure['billing'],
        readonly requestIds?: DesktopAgentRunFailure['requestIds'],
        readonly pendingManagedReceipt?: DesktopAgentRunFailure['pendingManagedReceipt']
    ) {
        super(code, message, failure?.httpStatus, failure?.retryAfterMs, { pendingManagedReceipt });
        this.name = 'ResumableAgentRunError';
    }
}

