const AGENT_JOB_TTL_MS = 30 * 60 * 1_000;
const AGENT_JOB_MAX_ENTRIES = 96;
const AGENT_JOB_MAX_EVENTS = 4_096;
const AGENT_JOB_MAX_EVENT_CHARACTERS = 4 * 1024 * 1024;
const AGENT_JOB_MAX_PENDING_MESSAGES = 24;
const AGENT_JOB_MAX_PENDING_CHARACTERS = 80_000;
const AGENT_CHILD_MAX_ENTRIES = 32;
const AGENT_CHILD_MAX_EVENTS = 2_048;
const AGENT_CHILD_MAX_EVENT_CHARACTERS = 1 * 1024 * 1024;

function validAgentIdentity(value: unknown, minimum = 8, maximum = 180): value is string {
    return typeof value === 'string' && value.length >= minimum && value.length <= maximum
        && /^[A-Za-z0-9._:-]+$/.test(value);
}

function compactAgentChildReceipt(value: AgentChildReceipt | undefined): AgentChildReceipt | undefined {
    if (!value || !['completed', 'partial', 'cancelled', 'failed', 'unknown'].includes(value.outcome)) return undefined;
    const tokenBudget = normalizeAgentTokenBudgetSnapshot(value.tokenBudget);
    const failure = value.failure && typeof value.failure.code === 'string' && typeof value.failure.message === 'string'
        ? {
            code: value.failure.code.slice(0, 160),
            message: value.failure.message
                .replace(/Bearer\s+[^\s,;]+/gi, 'Bearer [redacted]')
                .replace(/\b(?:sk|rk|pk|nmxm|nmxu)[-_][A-Za-z0-9._-]{8,}\b/g, '[redacted]')
                .replace(/[\u0000\r\n]+/g, ' ')
                .slice(0, 2_000)
        }
        : undefined;
    return {
        outcome: value.outcome,
        retrySafe: value.retrySafe === true,
        unknownSideEffect: value.unknownSideEffect === true,
        summary: typeof value.summary === 'string' ? value.summary.slice(0, 300) : '',
        ...(tokenBudget ? { tokenBudget } : {}),
        ...(failure ? { failure } : {})
    };
}

function compactAgentTokenBudget(value: AgentTokenBudgetSnapshot | undefined): AgentTokenBudgetSnapshot | undefined {
    return value === undefined ? undefined : normalizeAgentTokenBudgetSnapshot(value);
}

function sameAgentWorkspace(left: string, right: string): boolean {
    const normalize = (value: string): string => resolve(value).replace(/[\\/]+/g, sep).toLocaleLowerCase();
    return normalize(left) === normalize(right);
}

/**
 * Camera motion for a still image (Ken Burns), as zoompan expressions over `frames` output frames:
 * push in / pull out zoom 12 %, pans and tilts travel across a 12 % crop. Other motions stay still.
 */
export function comicImageMotion(motion: string | undefined): { zoom(frames: number): string; x(frames: number): string; y(frames: number): string } | undefined {
    const progress = (frames: number): string => `min(on/${Math.max(1, frames - 1)},1)`;
    const centerX = '(iw-iw/zoom)/2', centerY = '(ih-ih/zoom)/2';
    switch (motion) {
        case 'push_in': return { zoom: frames => `1+0.12*${progress(frames)}`, x: () => centerX, y: () => centerY };
        case 'pull_out': return { zoom: frames => `1.12-0.12*${progress(frames)}`, x: () => centerX, y: () => centerY };
        case 'pan_left': return { zoom: () => '1.12', x: frames => `(iw-iw/zoom)*(1-${progress(frames)})`, y: () => centerY };
        case 'pan_right': return { zoom: () => '1.12', x: frames => `(iw-iw/zoom)*${progress(frames)}`, y: () => centerY };
        case 'tilt_up': return { zoom: () => '1.12', x: () => centerX, y: frames => `(ih-ih/zoom)*(1-${progress(frames)})` };
        case 'tilt_down': return { zoom: () => '1.12', x: () => centerX, y: frames => `(ih-ih/zoom)*${progress(frames)}` };
        default: return undefined;
    }
}

