function proxyEndpoint(value: string, allowCredentials = false): string {
    const candidate = /^[a-z][a-z0-9+.-]*:\/\//i.test(value.trim()) ? value.trim() : `http://${value.trim()}`;
    let parsed: URL;
    try {
        parsed = new URL(candidate);
    } catch {
        throw new PlatformRequestError('INVALID_PROXY_URL', '代理地址格式无效');
    }
    if (!['http:', 'https:'].includes(parsed.protocol) || !parsed.hostname || parsed.pathname !== '/'
        || parsed.search || parsed.hash || (!allowCredentials && (parsed.username || parsed.password))) {
        throw new PlatformRequestError('INVALID_PROXY_URL', '代理地址必须是不含凭据和路径的 HTTP 或 HTTPS 地址');
    }
    return parsed.toString().replace(/\/$/, '');
}

function proxyDisplay(value: string | undefined): string {
    if (!value) return '';
    try {
        const parsed = new URL(value);
        return `${parsed.protocol}//${parsed.hostname}${parsed.port ? `:${parsed.port}` : ''}`;
    } catch {
        return '';
    }
}

function commandOutput(file: string, args: readonly string[]): Promise<string> {
    return new Promise((resolveOutput, rejectOutput) => {
        execFile(file, [...args], { encoding: 'utf8', timeout: 2_500, maxBuffer: 128 * 1024, windowsHide: true }, (error, stdout) => {
            if (error) rejectOutput(error);
            else resolveOutput(String(stdout || ''));
        });
    });
}

function commandBytes(file: string, args: readonly string[], timeoutMs = 2_500): Promise<Buffer> {
    return new Promise((resolveOutput, rejectOutput) => {
        execFile(file, [...args], { encoding: null, timeout: timeoutMs, maxBuffer: 128 * 1024, windowsHide: true }, (error, stdout) => {
            if (error) rejectOutput(error);
            else resolveOutput(Buffer.isBuffer(stdout) ? stdout : Buffer.from(stdout || ''));
        });
    });
}

function boundedCommand(file: string, args: readonly string[], cwd: string, timeoutMs = 8_000): Promise<BoundedCommandResult> {
    return new Promise((resolveCommand, rejectCommand) => {
        const child = spawn(file, [...args], { cwd, windowsHide: true, shell: false, stdio: ['ignore', 'pipe', 'pipe'] });
        let stdout = '';
        let stderr = '';
        const append = (current: string, chunk: Buffer): string => `${current}${chunk.toString('utf8')}`.slice(-512_000);
        child.stdout?.on('data', chunk => { stdout = append(stdout, chunk as Buffer); });
        child.stderr?.on('data', chunk => { stderr = append(stderr, chunk as Buffer); });
        const timeout = setTimeout(() => child.kill(), timeoutMs);
        child.once('error', error => {
            clearTimeout(timeout);
            rejectCommand(error);
        });
        child.once('close', code => {
            clearTimeout(timeout);
            resolveCommand({ exitCode: typeof code === 'number' ? code : -1, stdout, stderr });
        });
    });
}

function environmentNetworkProxy(): ResolvedNetworkProxy | undefined {
    const httpsProxy = process.env.HTTPS_PROXY || process.env.https_proxy || process.env.ALL_PROXY || process.env.all_proxy;
    const httpProxy = process.env.HTTP_PROXY || process.env.http_proxy || process.env.ALL_PROXY || process.env.all_proxy;
    if (!httpsProxy && !httpProxy) return undefined;
    try {
        return {
            ...(httpProxy ? { httpProxy: proxyEndpoint(httpProxy, true) } : {}),
            ...(httpsProxy ? { httpsProxy: proxyEndpoint(httpsProxy, true) } : {}),
            noProxy: process.env.NO_PROXY || process.env.no_proxy || '',
            source: 'environment'
        };
    } catch {
        return undefined;
    }
}

function windowsProxyValue(output: string, name: string): string {
    const match = output.match(new RegExp(`^\\s*${name}\\s+REG_[A-Z0-9_]+\\s+(.+?)\\s*$`, 'im'));
    return match?.[1]?.trim() || '';
}

function windowsProxyEndpoint(server: string): string {
    const map = new Map<string, string>();
    let fallback = '';
    for (const segment of server.split(';').map(value => value.trim()).filter(Boolean)) {
        const separator = segment.indexOf('=');
        if (separator > 0) map.set(segment.slice(0, separator).toLowerCase(), segment.slice(separator + 1));
        else fallback = segment;
    }
    return map.get('https') || map.get('http') || fallback;
}

async function operatingSystemNetworkProxy(): Promise<ResolvedNetworkProxy | undefined> {
    try {
        if (process.platform === 'win32') {
            const output = await commandOutput('reg.exe', ['query', 'HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings']);
            if (!/^\s*ProxyEnable\s+REG_DWORD\s+0x1\s*$/im.test(output)) return undefined;
            const endpoint = windowsProxyEndpoint(windowsProxyValue(output, 'ProxyServer'));
            if (!endpoint) return undefined;
            const proxy = proxyEndpoint(endpoint);
            const noProxy = windowsProxyValue(output, 'ProxyOverride').split(';').filter(value => value && value !== '<local>').join(',');
            return { httpProxy: proxy, httpsProxy: proxy, noProxy, source: 'operating_system' };
        }
        if (process.platform === 'darwin') {
            const output = await commandOutput('/usr/sbin/scutil', ['--proxy']);
            const value = (name: string): string => output.match(new RegExp(`^\\s*${name}\\s*:\\s*(.+?)\\s*$`, 'im'))?.[1]?.trim() || '';
            const enabled = value('HTTPSEnable') === '1' || value('HTTPEnable') === '1';
            if (!enabled) return undefined;
            const host = value('HTTPSProxy') || value('HTTPProxy');
            const port = value('HTTPSPort') || value('HTTPPort');
            if (!host) return undefined;
            const proxy = proxyEndpoint(`${host}${port ? `:${port}` : ''}`);
            return { httpProxy: proxy, httpsProxy: proxy, source: 'operating_system' };
        }
        if (process.platform === 'linux') {
            const mode = (await commandOutput('gsettings', ['get', 'org.gnome.system.proxy', 'mode'])).replace(/['"\s]/g, '');
            if (mode !== 'manual') return undefined;
            const host = (await commandOutput('gsettings', ['get', 'org.gnome.system.proxy.https', 'host'])).replace(/^'|'$/g, '').trim()
                || (await commandOutput('gsettings', ['get', 'org.gnome.system.proxy.http', 'host'])).replace(/^'|'$/g, '').trim();
            const port = (await commandOutput('gsettings', ['get', 'org.gnome.system.proxy.https', 'port'])).trim()
                || (await commandOutput('gsettings', ['get', 'org.gnome.system.proxy.http', 'port'])).trim();
            if (!host) return undefined;
            const proxy = proxyEndpoint(`${host}${port ? `:${port}` : ''}`);
            return { httpProxy: proxy, httpsProxy: proxy, source: 'operating_system' };
        }
    } catch {
    }
    return undefined;
}

function gitRemoteWebAddress(value: string): { readonly url: string; readonly provider: DesktopGitState['provider'] } {
    const trimmed = value.trim();
    if (!trimmed || /[\r\n\0]/.test(trimmed)) return { url: '', provider: 'none' };
    let candidate = trimmed;
    const scp = candidate.match(/^git@([^:]+):(.+)$/i);
    if (scp) candidate = `https://${scp[1]}/${scp[2]}`;
    else if (candidate.startsWith('ssh://')) {
        try {
            const ssh = new URL(candidate);
            candidate = `https://${ssh.hostname}${ssh.pathname}`;
        } catch {
            return { url: '', provider: 'other' };
        }
    }
    let url: URL;
    try { url = new URL(candidate); } catch { return { url: '', provider: 'other' }; }
    if (!['http:', 'https:'].includes(url.protocol) || !url.hostname) return { url: '', provider: 'other' };
    url.username = '';
    url.password = '';
    url.search = '';
    url.hash = '';
    url.pathname = url.pathname.replace(/\.git\/?$/i, '').replace(/\/+$/, '');
    const hostname = url.hostname.toLowerCase();
    const provider: DesktopGitState['provider'] = hostname === 'github.com' ? 'github'
        : hostname.includes('gitlab') ? 'gitlab'
            : hostname === 'bitbucket.org' ? 'bitbucket'
                : hostname === 'gitee.com' ? 'gitee' : 'other';
    return { url: url.toString().replace(/\/$/, ''), provider };
}

function pullRequestAddress(webUrl: string, provider: DesktopGitState['provider'], branch: string): string {
    if (!webUrl || !branch || branch === 'HEAD') return '';
    const encoded = encodeURIComponent(branch);
    if (provider === 'github') return `${webUrl}/compare/${encoded}?expand=1`;
    if (provider === 'gitlab') return `${webUrl}/-/merge_requests/new?merge_request[source_branch]=${encoded}`;
    if (provider === 'bitbucket') return `${webUrl}/pull-requests/new?source=${encoded}`;
    if (provider === 'gitee') return `${webUrl}/pulls/new/${encoded}`;
    return webUrl;
}

function stripTerminalControl(value: string): string {
    return value.replace(/\u001B\][^\u0007]*(?:\u0007|\u001B\\)/g, '').replace(/\u001B\[[0-?]*[ -/]*[@-~]/g, '');
}

function xmlText(value: string): string {
    return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}

