/**
 * A path as an FFmpeg filter option value. The value passes two parsers: the filter's option parser (escape \\ ' :)
 * and then the filtergraph parser (escape \\ ' [ ] , ;). Quoting it instead breaks on a folder named "it's"
 * (audit B15-009).
 */
function ffmpegFilterValue(value: string): string {
    const optionLevel = value.replace(/[\\':]/g, match => `\\${match}`);
    return optionLevel.replace(/[\\'\[\],;]/g, match => `\\${match}`);
}

/**
 * The prompt plus what to avoid, within the model's prompt limit (audit B15-008). The prompt itself is never cut:
 * the avoid list is shortened, or left out, to fit.
 */
function promptWithAvoid(prompt: string, negative: string | undefined, label: string, maxChars?: number): string {
    const avoid = negative?.trim();
    if (!avoid) return prompt;
    const full = `${prompt}\n\n${label}${avoid}`;
    if (!maxChars || full.length <= maxChars) return full;
    const room = maxChars - prompt.length - 2 - label.length;
    if (room < 24) return prompt;
    const cut = avoid.slice(0, room);
    const clean = cut.lastIndexOf(',') > room / 2 ? cut.slice(0, cut.lastIndexOf(',')) : cut;
    return `${prompt}\n\n${label}${clean.trim()}`;
}

/** Dialogue as ASS text: braces and backslashes would start override tags, so they become full-width look-alikes (audit B15-010). */
function assDialogueText(text: string): string {
    return text.replace(/\\/g, '＼').replace(/{/g, '｛').replace(/}/g, '｝').replace(/\r\n?|\n/g, '\\N').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g, '');
}

/**
 * How long to wait before polling a media job again: its first interval for the first minutes, then gradually up to a
 * minute, so a job that sits in a provider's queue for hours or days is followed without flooding it with requests.
 */
export function mediaPollDelay(startedAt: number, first: number, now = Date.now()): number {
    const elapsed = Math.max(0, now - startedAt);
    return Math.min(60_000, first + Math.floor(Math.max(0, elapsed - 5 * 60_000) / 60));
}

