                    // decision means no eligible slot: fail visibly instead of silently running the specialist on the parent route.
                    if (councilConfig && !decision) throw new AgentToolError('COUNCIL_ROUTE_UNAVAILABLE',
                        'No eligible specialist route is available. Continue this subtask yourself and report that no specialist participated.');
                    const slot = decision ? councilConfig?.slots.find(x => x.slotId === decision.slotId) : {
                        slotId: 'durable-parent-route', modelId: requestedOfficialModel || 'selected-managed-model', modelLabel: 'Selected parent route',
                        roles: ['generalist' as const], route: request.route };
                    if (!slot) throw new AgentToolError('DURABLE_ROUTE_UNAVAILABLE', 'The selected Council slot is unavailable');
                    const prepared = await prepareCouncilSlot(slot);
                    const generation = await durableOperations.credentialGeneration(owner, prepared.identity, prepared.credentialIdentity);
                    const requestFingerprint = durableFingerprint({ input: childReq.input, taskContext: durableLogicalContext(childReq.taskContext),
                        maxTurns: childReq.maxTurns, tokenBudget: childReq.tokenBudget, logicalParentOperationId: binding.logicalParentOperationId });
                    const executionFingerprint = durableFingerprint({ version: 1, councilConfig, decision, routeIdentity: prepared.identity, generation,
                        workspaceRoot, workspaceBindings: request.workspaceBindings, conversationId: stateConversationId,
                        privacy: { dataRoot: this.localConversationDataRoot(stateConversationId), workbench: request.workbench, toolScope: request.toolScope }, switchPolicy: request.switchPolicy, instructions: baseRunInstructions,
                        allowedTools: delegatedToolNames.map(name => tools.descriptor(name)), permission: effectivePermissionMode,
                        reasoning: [request.reasoningEffort, request.reasoningBudgetTokens, request.reasoningEnabled, request.reasoningExclude, request.reasoningMode],
                        selectedMemory: childReq.taskContext.selectedMemory, toolPolicy: context.toolPolicy });
                    const retry = execution.durableRetryIntent;
                    const assertRetryActive = (): void => {
                        if (retry && (execution.signal?.aborted || retry.cancelToken && this.withdrawnAgentStarts.has(retry.cancelToken)))
                            throw new AgentToolError('CANCELLED', 'The explicit retry was withdrawn before dispatch');
                    };
                    assertRetryActive();
