                        const check = await prepareCouncilSlot(slot);
                        const checkGeneration = await durableOperations.credentialGeneration(owner, check.identity, check.credentialIdentity);
                        if (durableFingerprint(check.identity) !== durableFingerprint(prepared.identity) || checkGeneration !== generation)
                            throw new AgentToolError('DURABLE_ROUTE_CHANGED', 'The selected route changed before retry authorization');
                        assertRetryActive();
                        releaseExecution = await durableOperations.acquireExecutionLease(owner, binding.operationId);
