                        let childLease: AgentCheckpointLease | undefined;
                        let child: Awaited<ReturnType<typeof delegatedWorkspaces.prepare>> | undefined;
                        try {
                            child = await delegatedWorkspaces.prepare({ ...input, conversationId: stateConversationId, rootRunId: delegationRootRunId,
                                beforeRuntimeCreate: async childRoot => {
                                    // Runtime construction can recover checkpoint files and
                                    // append to the tool ledger before prepare returns.
                                    // Keep this child lease through parent diagnostics.
                                    childLease = await this.acquireAgentCheckpointRunLeases([childRoot]);
                                    childCheckpointLeases.push(childLease);
                                }
                            });
                            // Skills remain verified against the originally approved source;
                            // only their knowledge loader is shared, never workspace executors.
                            await this.registerSkills(child.tools, request.skills, workspaceRoot);
                            return child;
                        } catch (error) {
                            if (child) {
                                const preparedChild = child;
                                await (childLease ? preparedChild.review().catch(() => preparedChild.dispose())
                                    : preparedChild.dispose()).catch(cleanupError => {
                                    console.error('[nextmux] unable to dispose failed child workspace', cleanupError);
                                });
                            }
                            if (childLease) {
                                const index = childCheckpointLeases.indexOf(childLease);
                                if (index >= 0) childCheckpointLeases.splice(index, 1);
                                await childLease.release().catch(releaseError => {
                                    console.error('[nextmux] unable to release failed child checkpoint lease', releaseError);
                                });
                            }
                            throw error;
                        }
