        registry.register({
            name: 'comic.apply_adaptation',
            description: 'Apply a complete novel adaptation in one atomic write: characters (merged by name; existing characters keep their appearance), then episodes → scenes → shots written for video generation. mode "replace" (default) removes the current scenes first; "append" adds after them. Call once with the whole adaptation.',
            requiredPermission: 'workspace_write',
            source: 'comic',
            inputSchema: {
                type: 'object', required: ['episodes'],
                properties: {
                    mode: { type: 'string', enum: ['replace', 'append', 'episode'] },
                    title: { type: 'string', maxLength: 120 },
                    styleBible: { type: 'string', maxLength: 4000 },
                    characters: { type: 'array', maxItems: 40, items: { type: 'object', required: ['name'], properties: {
                        name: { type: 'string' }, aliases: { type: 'array', items: { type: 'string' } }, role: { type: 'string' }, appearance: { type: 'string' }, costume: { type: 'string' }, voice: { type: 'string' }, personality: { type: 'string' } } } },
                    episodes: { type: 'array', minItems: 1, maxItems: 24, items: { type: 'object', required: ['scenes'], properties: {
                        number: { type: 'integer', minimum: 1 }, title: { type: 'string' },
                        scenes: { type: 'array', items: { type: 'object', required: ['shots'], properties: {
                            title: { type: 'string' }, summary: { type: 'string' }, location: { type: 'string' }, timeOfDay: { type: 'string' },
                            shots: { type: 'array', items: { type: 'object', required: ['visualPrompt'], properties: {
                                title: { type: 'string' }, durationSeconds: { type: 'number' }, shotSize: { type: 'string', enum: shotSizes }, cameraMotion: { type: 'string', enum: cameraMotions },
                                cameraAngle: { type: 'string', enum: ['eye_level', 'low', 'high', 'overhead', 'over_the_shoulder', 'pov', 'dutch'] },
                                lens: { type: 'object', required: ['focalLength', 'depthOfField'], properties: { focalLength: { type: 'string', enum: ['wide', 'normal', 'telephoto'] }, depthOfField: { type: 'string', enum: ['shallow', 'deep'] } } },
                                transition: { type: 'string', enum: ['cut', 'dissolve', 'fade'] }, continuousTakeId: { type: 'string' },
                                beats: { type: 'array', items: { type: 'object', required: ['startSeconds', 'endSeconds', 'action'], properties: { startSeconds: { type: 'number' }, endSeconds: { type: 'number' }, action: { type: 'string' } } } },
                                searchTerms: { type: 'array', minItems: 3, maxItems: 6, items: { type: 'string' } },
                                characters: { type: 'array', items: { type: 'string' } }, action: { type: 'string' }, visualPrompt: { type: 'string' }, negativePrompt: { type: 'string' },
                                dialogue: { type: 'array', items: { type: 'object', required: ['text'], properties: { speaker: { type: 'string' }, text: { type: 'string' }, tone: { type: 'string' } } } },
                                sound: { type: 'string' }, mood: { type: 'string' } } } } } } } } } }
                }
            }
        }, async input => {
            const args = comicToolArguments(input);
            const project = await readProject();
            let adaptation;
            try { adaptation = parseComicAdaptation(args); } catch (error) { return this.comicToolFailure(error); }
            // A project with episode scripts is storyboarded one episode at a time: only that episode is replaced.
            const mode = args.mode === 'append' ? 'append' : args.mode === 'episode' || project.episodes?.length ? 'episode' : 'replace';
            const settings = project.adaptSettings;
            if (mode === 'episode') {
                // One scene per heading of the episode's script: folding them loses the sets (every clip gets the first place).
                for (const episode of adaptation.episodes) {
                    const headings = comicScriptSceneHeadings(project.episodes?.find(item => item.number === episode.number)?.script || '');
                    if (headings.length >= 2 && episode.scenes.length < headings.length) {
                        throw new AgentToolError('SCENE_COUNT_MISMATCH', `Episode ${episode.number}'s script has ${headings.length} scenes (${headings.join(' / ')}) but you made ${episode.scenes.length}. Make one scene per heading, in order, each with that heading's place as location and its time as timeOfDay, and call comic.apply_adaptation again with the whole episode.`);
                    }
                }
            }
            const planIssues = comicShotPlanIssues(adaptation, { silent: settings?.sound === 'silent' });
            if (planIssues.length && shotPlanReturns < 2) {
                shotPlanReturns += 1;
                throw new AgentToolError('SHOT_PLAN_INCOMPLETE', comicShotPlanCorrection(planIssues));
            }
            if (settings && mode === 'episode') {
                // The episode must come close to its target length; the rest is fitted exactly below.
                for (const episode of adaptation.episodes) {
                    const seconds = episode.scenes.reduce((sum, scene) => sum + scene.shots.reduce((total, shot) => total + shot.durationSeconds, 0), 0);
                    if (seconds < settings.episodeSeconds * 0.6 || seconds > settings.episodeSeconds * 1.7) {
                        throw new AgentToolError('EPISODE_LENGTH_MISMATCH', `Episode ${episode.number} runs ${Math.round(seconds)} seconds but should run about ${settings.episodeSeconds} seconds. ${seconds < settings.episodeSeconds ? 'Add shots or lengthen them' : 'Remove or shorten shots'} and call comic.apply_adaptation again with the whole episode.`);
                    }
                }
            }
            try {
                // Clips finishing meanwhile (episode 1 films while episode 2 is split) move the revision on:
                // apply the same shots to the latest project instead of failing the whole tool call.
                let result!: ReturnType<typeof applyComicAdaptation>;
                let latest = project;
                const state = await this.retryOnComicRevision(async () => {
                    result = applyComicAdaptation(latest, adaptation, {
                        mode, locale: latest.defaultTitleLocale ?? latest.titleDefault?.locale,
                        ...(settings && mode === 'episode' ? { fitDurations: { clipSeconds: settings.clipSeconds || [], episodeSeconds: settings.episodeSeconds } } : {})
                    });
                    try { return await store.commitPrepared(latest.revision, result.project); } catch (error) {
                        if ((error as { code?: string })?.code === 'REVISION_CONFLICT') latest = await readProject();
                        throw error;
                    }
                });
                return {
                    modelOutput: boundedJsonValue({ revision: state.project!.revision, characters: result.characters, episodes: result.episodes, scenes: result.scenes, shots: result.shots, durationSeconds: Math.round(result.durationSeconds) }, 4_000),
                    summary: { kind: 'comic.apply_adaptation', params: { episodes: result.episodes, scenes: result.scenes, shots: result.shots, durationSeconds: Math.round(result.durationSeconds) }, title: 'Apply storyboard adaptation' }
                };
            } catch (error) {
                return this.comicToolFailure(error);
            }
        });

