                if (lyrics.length > 3_500) throw new AgentToolError('LYRICS_TOO_LONG', `The lyrics have ${lyrics.length} characters; keep them under 3500 and call comic.write_lyrics again.`);
                const current = project.music;
                const style = typeof args.style === 'string' && args.style.trim() ? args.style.trim().slice(0, 2_000) : current?.style || '';
