        registry.register({
            name: 'comic.write_scripts',
            description: 'Part one of a novel adaptation: save the series bible (title, styleBible, characters merged by name) and one screenplay per episode. Shots are made later from each script. mode "replace" (default) replaces all episode scripts; "append" adds a sequel after the existing episodes and leaves them untouched.',
            requiredPermission: 'workspace_write',
            source: 'comic',
            inputSchema: {
                type: 'object', required: ['episodes'],
                properties: {
                    mode: { type: 'string', enum: ['replace', 'append'] },
                    title: { type: 'string', maxLength: 120 },
                    styleBible: { type: 'string', maxLength: 4000 },
                    characters: { type: 'array', maxItems: 40, items: { type: 'object', required: ['name'], properties: {
                        name: { type: 'string' }, aliases: { type: 'array', items: { type: 'string' } }, role: { type: 'string' }, appearance: { type: 'string' }, costume: { type: 'string' }, voice: { type: 'string' }, personality: { type: 'string' } } } },
                    episodes: { type: 'array', minItems: 1, maxItems: 100, items: { type: 'object', required: ['script'], properties: {
                        number: { type: 'integer', minimum: 1 }, title: { type: 'string' }, script: { type: 'string' },
                        outline: { type: 'string' }, ending: { type: 'string' }, sourceRange: { type: 'object', required: ['start', 'end'], properties: { start: { type: 'integer', minimum: 0 }, end: { type: 'integer', minimum: 1 } } } } } }
                }
            }
        }, async input => {
            const args = comicToolArguments(input);
            const project = await readProject();
            try {
                const scripts = parseComicScripts(args);
                const mode = args.mode === 'append' ? 'append' : 'replace';
                // A sequel's count is the new episodes; they are numbered on from the last existing one.
                const first = mode === 'append' ? (project.episodes || []).reduce((last, episode) => Math.max(last, episode.number), 0) + 1 : 1;
                const wanted = project.adaptSettings?.episodes;
                if (wanted && scripts.episodes.length !== wanted) {
                    throw new AgentToolError('EPISODE_COUNT_MISMATCH', `The user asked for exactly ${wanted} episode${wanted === 1 ? '' : 's'}; you wrote ${scripts.episodes.length}. Call comic.write_scripts again with exactly ${wanted}, numbered ${first} to ${first + wanted - 1}${mode === 'append' ? ' and mode "append"' : ''}.`);
                }
                const next = applyComicScripts(project, scripts, { mode, locale: project.defaultTitleLocale ?? project.titleDefault?.locale });
                const state = await store.commitPrepared(project.revision, next);
                return {
                    modelOutput: boundedJsonValue({ revision: state.project!.revision, episodes: scripts.episodes.length, characters: scripts.characters.length }, 2_000),
                    summary: { kind: 'comic.write_scripts', params: { episodes: scripts.episodes.length, characters: scripts.characters.length }, title: 'Write scripts' }
                };
            } catch (error) {
                return this.comicToolFailure(error);
            }
        });

        registry.register({
            name: 'comic.replace_dialogue',
            description: 'Replace the complete timed dialogue list for one shot. Omitted timings are distributed sequentially across the shot; an empty cues array clears dialogue.',
            requiredPermission: 'workspace_write',
            source: 'comic',
            inputSchema: {
                type: 'object', additionalProperties: false, required: ['expectedRevision', 'sceneId', 'shotId', 'cues'],
                properties: {
                    expectedRevision: { type: 'integer', minimum: 0 },
                    sceneId: { type: 'string' },
                    shotId: { type: 'string' },
                    cues: {
                        type: 'array', maxItems: 50,
                        items: {
                            type: 'object', additionalProperties: false, required: ['text'],
                            properties: {
                                id: { type: 'string' },
                                speakerCharacterId: { type: 'string' },
                                text: { type: 'string', minLength: 1, maxLength: 5000 }, tone: { type: 'string', maxLength: 500 },
                                startSeconds: { type: 'number', minimum: 0, maximum: 600 },
                                durationSeconds: { type: 'number', exclusiveMinimum: 0, maximum: 600 }
                            }
                        }
                    }
                }
            }
        }, async input => {
            const args = comicToolArguments(input);
            const project = await readProject();
            const sceneId = comicToolString(args.sceneId, 'sceneId', { required: true, maximum: 120 })!;
            const shotId = comicToolString(args.shotId, 'shotId', { required: true, maximum: 120 })!;
            const shot = project.scenes.find(candidate => candidate.id === sceneId)
                ?.shots.find(candidate => candidate.id === shotId);
            if (!shot) throw new AgentToolError('SHOT_NOT_FOUND', 'Requested comic shot does not exist');
            if (!Array.isArray(args.cues) || args.cues.length > 50) {
                throw new AgentToolError('INVALID_COMIC_ARGUMENTS', 'cues must be an array with at most 50 items');
            }
            const cueRecords = args.cues.map((candidate, index) => {
                if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
                    throw new AgentToolError('INVALID_COMIC_ARGUMENTS', `cues[${index}] must be an object`);
                }
                return candidate as Record<string, unknown>;
            });
            const defaultSegmentFrames = cueRecords.length === 0 ? shot.durationFrames : shot.durationFrames / cueRecords.length;
            const startFrames = cueRecords.map((cue, index) => cue.startSeconds === undefined
                ? Math.min(shot.durationFrames - 1, Math.round(defaultSegmentFrames * index))
                : Math.round(comicToolNumber(
                    cue.startSeconds,
                    `cues[${index}].startSeconds`,
                    0,
                    (shot.durationFrames - 1) / project.frameRate
                ) * project.frameRate));
            const cues = cueRecords.map((cue, index) => {
                const startFrame = startFrames[index];
                const nextStart = startFrames[index + 1];
                const defaultDuration = nextStart !== undefined && nextStart > startFrame
                    ? nextStart - startFrame
                    : shot.durationFrames - startFrame;
                const durationFrames = cue.durationSeconds === undefined
                    ? Math.max(1, defaultDuration)
                    : Math.max(1, Math.round(comicToolNumber(
                        cue.durationSeconds,
                        `cues[${index}].durationSeconds`,
                        1 / project.frameRate,
                        (shot.durationFrames - startFrame) / project.frameRate
                    ) * project.frameRate));
                return {
                    ...(cue.id === undefined ? {} : {
                        id: comicToolString(cue.id, `cues[${index}].id`, { required: true, maximum: 120 })!
                    }),
                    ...(cue.speakerCharacterId === undefined ? {} : {
                        speakerCharacterId: comicToolString(
                            cue.speakerCharacterId,
                            `cues[${index}].speakerCharacterId`,
                            { required: true, maximum: 120 }
                        )!
                    }),
                    ...(cue.tone === undefined ? {} : { tone: comicToolString(cue.tone, `cues[${index}].tone`, { maximum: 500 }) }),
                    text: comicToolString(cue.text, `cues[${index}].text`, { required: true, maximum: 5_000 })!,
                    startFrame,
                    durationFrames
                };
            });
            return apply({
                type: 'dialogue.replace',
                expectedRevision: comicToolInteger(args.expectedRevision, 'expectedRevision', 0, Number.MAX_SAFE_INTEGER),
                sceneId,
                shotId,
                cues
            }, 'comic.replace_dialogue', 'Replace shot dialogue', sceneId);
        });

