    /** 上传插件到市场: the chosen .nmxplugin file (read here, never a path the page did not pick through the file dialog). */
    async uploadAppPluginToMarket(request: { readonly path: string; readonly author: string; readonly priceCents?: number }): Promise<AppPluginMarketUpload> {
        const path = typeof request?.path === 'string' ? request.path : '';
        if (!path || path.length > 4_096 || path.includes('\0') || !isAbsolute(path) || !/\.(nmxplugin|zip)$/i.test(path)) return { ok: false, problem: { code: 'plugin_file_invalid' } };
        const info = await lstat(path).catch(() => undefined);
        if (!info?.isFile() || info.isSymbolicLink()) return { ok: false, problem: { code: 'plugin_file_invalid' } };
        if (info.size > 20 * 1024 * 1024) return { ok: false, problem: { code: 'package_size' } };
        const bytes = await readFile(path);
        return uploadAppPluginToMarket({ baseUrl: this.baseUrl, fetch: this.networkFetch, deviceId: () => this.deviceId() },
            bytes, basename(path), typeof request.author === 'string' ? request.author : '', request.priceCents === undefined || request.priceCents === null ? undefined : Number(request.priceCents));
    }

